import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int count = (int) n;
        long[] all = new long[32 * count + 32];
        int total = 0;
        long[] cur = new long[64];
        int size = 0;
        for (int idx = 0; idx < count; idx++) {
            long x = a[idx];
            long[] nxt = new long[64];
            int ns = 0;
            for (int i = 0; i < size; i++) nxt[ns++] = cur[i] | x;
            nxt[ns++] = x;
            Arrays.sort(nxt, 0, ns);
            int u = 0;
            for (int i = 0; i < ns; i++) {
                if (u == 0 || nxt[u - 1] != nxt[i]) nxt[u++] = nxt[i];
            }
            cur = nxt;
            size = u;
            for (int i = 0; i < size; i++) all[total++] = cur[i];
        }
        Arrays.sort(all, 0, total);
        long distinct = 0;
        for (int i = 0; i < total; i++) {
            if (i == 0 || all[i] != all[i - 1]) distinct++;
        }
        System.out.println(distinct);
    }
}
